import XCTest
@testable import EcuCore

/// Differential tests: outputs of the Swift port vs. reference outputs produced by
/// running the ORIGINAL Java classes (Ecu.java etc.) on the same inputs.
/// Reference files: Resources/oracle/*.jsonl (generated by tools/oracle).
final class OracleTests: XCTestCase {

    static var resources: URL {
        Bundle.module.url(forResource: "Resources", withExtension: nil)
            ?? Bundle.module.bundleURL.appendingPathComponent("Resources")
    }

    func lines(_ name: String) throws -> [[String: Any]] {
        let url = Self.resources.appendingPathComponent("oracle").appendingPathComponent(name)
        let text = try String(contentsOf: url, encoding: .utf8)
        return text.split(separator: "\n").compactMap {
            try? JSONSerialization.jsonObject(with: Data($0.utf8)) as? [String: Any]
        }
    }

    func loadEcu(_ file: String) throws -> Ecu {
        let data = try Data(contentsOf: Self.resources.appendingPathComponent(file))
        return try Ecu(data: data)
    }

    struct Stats { var ok = 0; var mismatches = [String]() }

    func compareEcu(_ file: String) throws -> (decode: Stats, encode: Stats) {
        let ecu = try loadEcu(file)
        var dec = Stats(), enc = Stats()
        for o in try lines(file + ".jsonl") {
            let kind = o["kind"] as? String
            if kind == "sds" {
                let javaSds = o["sds"] as? [String: String] ?? [:]
                XCTAssertEqual(ecu.sdsRequests, javaSds, "\(file): SDS request map")
                XCTAssertEqual(ecu.defaultSDS, o["default"] as? String, "\(file): default SDS")
                continue
            }
            let req = o["req"] as! String
            if kind == "decode" {
                let bytes = try JavaCompat.hexStringToBytes(o["bytes"] as! String)
                let swift = try? ecu.requestValues(bytes, request: req, withUnits: true)
                if let expected = o["values"] as? [String: String] {
                    if swift == expected { dec.ok += 1 }
                    else if let swift, Self.knownDecodeDifference(ecu, expected, swift) { dec.ok += 1 }
                    else {
                        let diff = expected.keys.filter { swift?[$0] != expected[$0] }.prefix(3)
                            .map { "\($0): java=\(expected[$0]!) swift=\(swift?[$0] ?? "<throw>")" }
                        dec.mismatches.append("\(req) [\(o["bytes"]!)] " + diff.joined(separator: "; "))
                    }
                } else {
                    if swift == nil { dec.ok += 1 } else { dec.mismatches.append("\(req): java threw, swift returned") }
                }
            } else if kind == "encode" {
                let values = o["values"] as? [String: String] ?? [:]
                let order = o["order"] as? [String] ?? values.keys.sorted()
                let swift = try? ecu.setRequestValues(req, ordered: order.map { ($0, values[$0]!) })
                let swiftHex = swift.map(JavaCompat.bytesToHex)
                if let expected = o["frame"] as? String {
                    if swiftHex == expected { enc.ok += 1 }
                    else { enc.mismatches.append("\(req) \(values) java=\(expected) swift=\(swiftHex ?? "<throw>")") }
                } else {
                    if swiftHex == nil { enc.ok += 1 }
                    else { enc.mismatches.append("\(req) \(values): java threw \(o["error"] ?? ""), swift=\(swiftHex!)") }
                }
            }
        }
        return (dec, enc)
    }

    func report(_ file: String, _ s: (decode: Stats, encode: Stats), allowEncode: (String) -> Bool = { _ in false }) {
        print("[\(file)] decode ok=\(s.decode.ok) mismatch=\(s.decode.mismatches.count); encode ok=\(s.encode.ok) mismatch=\(s.encode.mismatches.count)")
        for m in s.decode.mismatches.prefix(10) { print("  DEC ", m) }
        let realEnc = s.encode.mismatches.filter { !allowEncode($0) }
        for m in realEnc.prefix(10) { print("  ENC ", m) }
        XCTAssertEqual(s.decode.mismatches.count, 0, "\(file) decode mismatches")
        XCTAssertEqual(realEnc.count, 0, "\(file) encode mismatches")
    }

    /// Known, intentional decode differences:
    ///  * DecimalFormat("bin"): Java prints "bin" + number; we print the number (like DDT4All);
    ///  * invalid UTF-8 in bytesascii items: replacement-character count differs.
    static func knownDecodeDifference(_ ecu: Ecu, _ java: [String: String], _ swift: [String: String]) -> Bool {
        guard java.keys.sorted() == swift.keys.sorted() else { return false }
        for (k, jv) in java where swift[k] != jv {
            let sv = swift[k]!
            if ecu.data[k]?.format == "bin", jv == "bin" + sv { continue }
            if jv.contains("\u{FFFD}") || sv.contains("\u{FFFD}") { continue }
            return false
        }
        return true
    }

    /// Known, intentional difference: negative scaled values are written as
    /// two's complement of the field width (Java wrote the top bits).
    static func isNegativeFix(_ m: String) -> Bool { m.contains("-") }

    func testTestJson() throws { report("test.json", try compareEcu("test.json"), allowEncode: Self.isNegativeFix) }
    func testUchLittleEndian() throws { report("UCH_LE.json", try compareEcu("UCH_LE.json"), allowEncode: Self.isNegativeFix) }
    func testAcu() throws { report("acu.json", try compareEcu("acu.json"), allowEncode: Self.isNegativeFix) }
    func testDdcrKwp() throws {
        report("DDCR_-_BEB2_a_BEB4_-_v5.0.json", try compareEcu("DDCR_-_BEB2_a_BEB4_-_v5.0.json"), allowEncode: Self.isNegativeFix)
    }

    func testFormats() throws {
        var fmtMismatch = 0, dfMismatch = 0, total = 0
        var samples = [String]()
        for o in try lines("formats.jsonl") {
            total += 1
            let bits = (o["bits"] as! NSNumber).int32Value
            let f = Float(bitPattern: UInt32(bitPattern: bits))
            let javaFmt = o["fmt"] as! String
            let swiftFmt = JavaCompat.fmt(Double(f))
            if swiftFmt != javaFmt {
                fmtMismatch += 1
                if samples.count < 10 { samples.append("fmt \(f): java=\(javaFmt) swift=\(swiftFmt)") }
            }
            for (pattern, expected) in o["df"] as! [String: String] {
                let got = JavaDecimalFormat(pattern: pattern)!.format(Double(f))
                if got != expected {
                    dfMismatch += 1
                    if samples.count < 20 { samples.append("df '\(pattern)' \(Double(f)): java=\(expected) swift=\(got)") }
                }
            }
        }
        print("[formats] total=\(total) fmt mismatches=\(fmtMismatch) DecimalFormat mismatches=\(dfMismatch)")
        samples.forEach { print("  ", $0) }
        XCTAssertEqual(fmtMismatch, 0)
        // OpenJDK breaks exact-decimal ties using the binary value while Android/ICU
        // rounds the shortest representation; allow a tiny number of such ties.
        XCTAssertLessThan(Double(dfMismatch) / Double(total * 12), 0.001)
    }
}
